INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_61_m_61_2_49',
  'Which AWS service provides on-demand access to AWS security and compliance reports and agreements?',
  'mcq',
  '["AWS Artifact.","AWS Config.","AWS CloudTrail.","AWS Security Hub."]'::json,
  '{0}',
  'Option A (correct) is AWS Artifact, which is the service that provides customers with on-demand access to AWS''s security and compliance reports and agreements. Option B (incorrect) is for configuration management, Option C (incorrect) is for API call logging, and Option D (incorrect) is for centralizing security findings. This question tests knowledge of where to find compliance documentation (ap-2.2-001).',
  NOW(),
  'quiz_domain61_13',
  NOW(),
