INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_62_m_62_7_46',
  'A company needs to process real-time clickstream data from its website to analyze user behavior and detect anomalies instantly. The data arrives continuously and requires immediate processing. Which AWS service is best suited for ingesting and processing this high-volume, real-time streaming data?',
