INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_62_m_62_7_50',
  'A company has large datasets stored in Amazon S3 that need to be transformed and prepared for analysis in a data warehouse. They require a serverless data integration service that can discover, transform, and move data between various data stores. Which AWS service should they use for this ETL (Extract, Transform, Load) process?',
