INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_62_m_62_8_35',
  'A company needs to process a large volume of sensor data from IoT devices in real-time, enabling communication between devices and the cloud. Which AWS service is central to managing and connecting IoT devices?',
  'mcq',
  '["Amazon S3","Amazon Kinesis","AWS IoT Core","AWS Lambda"]'::json,
  '{2}',
