INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_62_m_62_4_50',
  'A company needs a highly scalable, fully managed NoSQL database for an application with variable access patterns and high throughput requirements. Which AWS services are suitable? (Select TWO.)',
  'multiple',
  '["Amazon RDS","Amazon DynamoDB","Amazon Aurora","Amazon DocumentDB","Amazon Redshift"]'::json,
  '{1,3}',
  'Option B (Amazon DynamoDB) is a fully managed NoSQL (key-value and document) database that delivers single-digit millisecond performance at any scale, making it ideal for high throughput and variable access patterns. Option D (Amazon DocumentDB) is a fully managed native JSON document database that supports MongoDB workloads, suitable for document-oriented NoSQL needs. Option A (Amazon RDS) and Option C (Amazon Aurora) are relational databases. Option E (Amazon Redshift) is a data warehouse for analytics, not an operational NoSQL database.',
  NOW(),
  'quiz_domain62_13',
  NOW(),
  62,
  NULL,
  NULL,
  'm_62_4',
