INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_62_m_62_4_53',
  'To offload read traffic from a primary relational database and improve application responsiveness, which AWS services can be implemented? (Select TWO.)',
  'multiple',
  '["Amazon DynamoDB","Amazon ElastiCache","Amazon Aurora Read Replicas","Amazon Redshift","Amazon S3"]'::json,
  '{1,2}',
  'Option B (Amazon ElastiCache) provides in-memory caching, which can store frequently accessed data and significantly reduce the load on the primary database by serving reads from the cache. Option C (Amazon Aurora Read Replicas) allows you to create multiple read-only copies of your Aurora database, distributing read traffic and improving scalability for read-heavy applications. Option A (Amazon DynamoDB) is a NoSQL database, not a read replica or cache for relational databases. Option D (Amazon Redshift) is a data warehouse. Option E (Amazon S3) is object storage.',
  NOW(),
  'quiz_domain62_13',
  NOW(),
  65,
  NULL,
  NULL,
  'm_62_4',
  'easy'
) ON CONFLICT (id) DO NOTHING;

