INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_62_m_62_4_55',
  'A company needs a highly scalable, fully managed NoSQL database for an application with unpredictable, high-volume traffic patterns. Which AWS database services would be suitable? (Select TWO.)',
