INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_62_m_62_4_62',
  'A company is migrating its on-premises relational database to AWS and wants to minimize operational overhead for tasks like backups, patching, and scaling. Which AWS database services offer managed relational database capabilities? (Select TWO.)',
  'multiple',
  '["Amazon EC2 with self-managed database","Amazon RDS","Amazon DynamoDB","Amazon Aurora","Amazon ElastiCache"]'::json,
  '{1,3}',
  'Option B (Amazon RDS - Relational Database Service) and Option D (Amazon Aurora) are fully managed relational database services. They automate administrative tasks like backups, patching, scaling, and replication, significantly reducing operational overhead. Option A (Amazon EC2 with self-managed database) would require the customer to manually manage all database operations, increasing overhead. Option C (Amazon DynamoDB) is a managed NoSQL database, not relational. Option E (Amazon ElastiCache) is an in-memory caching service, not a primary relational database.',
  NOW(),
  'quiz_domain62_13',
  NOW(),
  74,
  NULL,
  NULL,
  'm_62_4',
  'medium'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_62_m_62_4_63',
  'Which AWS database services are fully managed and support a relational data model? (Select TWO.)',
  'multiple',
  '["Amazon DynamoDB","Amazon RDS","Amazon Redshift","Amazon Aurora","Amazon Neptune"]'::json,
  '{1,3}',
  'Option B (Amazon RDS - Relational Database Service) is a fully managed service that makes it easy to set up, operate, and scale a relational database in the cloud. Option D (Amazon Aurora) is a MySQL and PostgreSQL-compatible relational database built for the cloud, combining the performance and availability of high-end commercial databases with the simplicity and cost-effectiveness of open-source databases. Option A (Amazon DynamoDB) is a NoSQL database. Option C (Amazon Redshift) is a data warehouse, not a transactional relational database. Option E (Amazon Neptune) is a graph database.',
