INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_62_m_62_4_64',
  'Which AWS services are suitable for storing frequently accessed, non-relational data that requires high throughput and low latency? (Select TWO.)',
