-- Update quiz question count
UPDATE public.quiz q
SET questions = sub.cnt,
    modified_at = NOW()
FROM (
  SELECT quiz_id, COUNT(*)::int AS cnt
  FROM public.quiz_question
  WHERE quiz_id = 'quiz_domain63_13'
  GROUP BY quiz_id
) sub
WHERE q.id = sub.quiz_id;

COMMIT;
